    internal static (float Scale, FitVector Right, FitVector Left)? GetFit(string costumeModel, int appearance) =>
        costumeModel != null && Fits.TryGetValue(costumeModel, out var appearances) &&
        appearances.TryGetValue(appearance, out var fit) ? fit : null;
}
